var report=new System.Text.StringBuilder();foreach(var source in UnityEngine.Object.FindObjectsByType<UnityEngine.AudioSource>())if(source.name=="Hall Ventilation Emitter") {var data=new float[source.clip.samples];source.clip.GetData(data,0);double energy=0;float peak=0;foreach(float value in data){energy+=value*value;peak=UnityEngine.Mathf.Max(peak,UnityEngine.Mathf.Abs(value));}report.AppendLine("playing="+source.isPlaying+" mono="+(source.clip.channels==1)+" seconds="+source.clip.length+" peak="+peak+" rms="+System.Math.Sqrt(energy/data.Length)+" seam="+UnityEngine.Mathf.Abs(data[0]-data[data.Length-1]));}return report.ToString();
